import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert, Avatar, Box, Button, Card, CardContent, Chip, CircularProgress, Dialog,
  DialogActions, DialogContent, DialogTitle, Divider, IconButton, InputAdornment, LinearProgress,
  List, ListItemAvatar, ListItemButton, ListItemText, MenuItem, Paper, Stack, Tab, Table, TableBody,
  TableCell, TableContainer, TableHead, TableRow, Tabs, TextField, Tooltip, Typography,
  useMediaQuery, useTheme
} from '@mui/material';
import { toast } from 'react-hot-toast';
import { HealthVerticalService, VeterinaryService } from '../../services/verticalService.js';
import { SOAP_TEMPLATE_VERSION, resolveVeterinarySoapTemplate, veterinaryConsultationTypes } from './veterinarySoapTemplates.js';

const TABS = [
  ['resumen', 'Resumen', 'fa-chart-pie'], ['pacientes', 'Mascotas', 'fa-paw'], ['agenda', 'Agenda', 'fa-calendar-days'],
  ['historia', 'Historia clínica', 'fa-file-waveform'], ['laboratorio', 'Laboratorio', 'fa-flask-vial'], ['estudios', 'Estudios', 'fa-x-ray'],
  ['hospitalizacion', 'Hospitalización', 'fa-house-medical'], ['procedimientos', 'Procedimientos', 'fa-stethoscope'], ['comunicaciones', 'Comunicaciones', 'fa-message']
];
const STATUS_TONE = { scheduled:'info', confirmed:'success', checked_in:'warning', in_progress:'warning', completed:'success', cancelled:'default', no_show:'error', ordered:'info', processing:'warning', admitted:'error', observed:'warning', discharged:'success', critical:'error', high:'warning', low:'warning', abnormal:'warning', normal:'success', active:'success', pending:'warning', signed:'success', sent:'success', delivered:'success', failed:'error' };
const MONTHS = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const Icon = ({ name, size = 14 }) => <i className={`fa-solid ${name}`} style={{ fontSize:size }} aria-hidden="true" />;
const compactDate = (value) => value ? new Date(value).toLocaleString('es-VE', { dateStyle:'short', timeStyle:'short' }) : '—';
const onlyDate = (value) => value ? new Date(value).toLocaleDateString('es-VE') : '—';
const phoneDigits = (value) => String(value || '').replace(/\D/g, '');
const displayError = (error) => error?.message || 'No se pudo completar la operación.';
const reportVeterinaryError = (scope,error) => {
  console.error('[veterinary]', {
    scope,
    name:error?.name || 'Error',
    message:displayError(error),
    status:error?.status || error?.statusCode || null
  });
};
const arrayData = (value) => Array.isArray(value) ? value : value?.data || [];
const objectData = (value) => value?.data || value || {};
const shortCode = (value) => String(value || '').replaceAll('-', '').slice(0, 8).toUpperCase();
const localDateTime = (minutes = 0) => {
  const date = new Date(Date.now() + minutes * 60000 - new Date().getTimezoneOffset() * 60000);
  return date.toISOString().slice(0, 16);
};
const localDateTimeFromIso = (value) => {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value).slice(0, 16);
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
};

function Metric({ icon,label,value,hint,tone='primary' }) {
  return <Card sx={{minHeight:78}}><CardContent sx={{p:'11px!important',display:'grid',gridTemplateColumns:'30px minmax(0,1fr)',gap:1,alignItems:'start'}}><Avatar variant="rounded" sx={{width:30,height:30,borderRadius:'8px',bgcolor:'action.hover',color:`${tone}.main`,border:'1px solid',borderColor:'divider',fontSize:13}}><Icon name={icon}/></Avatar><Box sx={{minWidth:0}}><Typography variant="caption" color="text.secondary" sx={{fontWeight:600}}>{label}</Typography><Typography sx={{fontWeight:700,fontSize:'1rem',lineHeight:1.12,fontVariantNumeric:'tabular-nums',whiteSpace:'nowrap',overflow:'visible'}}>{value??0}</Typography>{hint&&<Typography variant="caption" color="text.secondary" noWrap>{hint}</Typography>}</Box></CardContent></Card>;
}
function StatusChip({value}) { return <Chip label={String(value||'pendiente').replaceAll('_',' ')} color={STATUS_TONE[value]||'default'} variant={value==='normal'?'outlined':'filled'}/>; }
function EmptyState({icon='fa-folder-open',title='Sin registros',text='Crea el primer registro para comenzar.'}) { return <Box sx={{py:2.5,px:2,textAlign:'left',color:'text.secondary'}}><Avatar variant="rounded" sx={{width:32,height:32,mb:1,borderRadius:'8px',bgcolor:'action.hover',color:'primary.main',border:'1px solid',borderColor:'divider'}}><Icon name={icon} size={14}/></Avatar><Typography variant="subtitle2" color="text.primary">{title}</Typography><Typography variant="caption">{text}</Typography></Box>; }
function SectionCard({title,subtitle,action,children,sx={}}) { return <Card sx={sx}><CardContent sx={{p:'13px!important'}}><Stack direction="row" gap={1} sx={{justifyContent:'space-between',alignItems:'flex-start',mb:1.2,flexWrap:'wrap'}}><Box sx={{minWidth:0}}><Typography variant="h6">{title}</Typography>{subtitle&&<Typography variant="caption" color="text.secondary">{subtitle}</Typography>}</Box>{action}</Stack>{children}</CardContent></Card>; }
function EntityLabel({primary,secondary,id}) { return <Box sx={{minWidth:0,py:.15}}><Typography component="span" sx={{display:'block',fontSize:'.8125rem',fontWeight:600,lineHeight:1.25,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{primary||'Sin nombre'}</Typography><Typography component="span" variant="caption" color="text.secondary" sx={{display:'block',letterSpacing:'.025em'}}>#{shortCode(id)}{secondary?` · ${secondary}`:''}</Typography></Box>; }

export function VeterinaryWorkspace({ state, UrlStateService }) {
  const query=UrlStateService.getParams(); const [tab,setTab]=useState(TABS.some(([k])=>k===query.tab)?query.tab:'resumen'); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(false); const [baseError,setBaseError]=useState(''); const [patientDataError,setPatientDataError]=useState(''); const [actionError,setActionError]=useState('');
  const [dashboard,setDashboard]=useState({}); const [patients,setPatients]=useState([]); const [professionals,setProfessionals]=useState([]); const [appointments,setAppointments]=useState([]); const [selectedPatientId,setSelectedPatientId]=useState(query.patient||'');
  const tabRef=useRef(tab); const patientRef=useRef(query.patient||''); const [encounters,setEncounters]=useState([]); const [prescriptions,setPrescriptions]=useState([]); const [consents,setConsents]=useState([]); const [labOrders,setLabOrders]=useState([]); const [labResults,setLabResults]=useState([]); const [studies,setStudies]=useState([]); const [hospitalizations,setHospitalizations]=useState([]); const [procedures,setProcedures]=useState([]); const [communications,setCommunications]=useState([]); const [dialog,setDialog]=useState(''); const [form,setForm]=useState({}); const [search,setSearch]=useState('');
  const selectedPatient=patients.find((x)=>x.id===selectedPatientId)||null; const theme=useTheme(); const mobile=useMediaQuery(theme.breakpoints.down('sm'));
  const field=(name,fallback='')=>form[name]??fallback; const setField=(name)=>(e)=>setForm((c)=>({...c,[name]:e.target.value}));
  const updateUrl=(nextTab,patientId)=>{const current=UrlStateService.getParams();const params={...current,tab:nextTab||tabRef.current||'resumen'};const next=patientId||patientRef.current;if(next)params.patient=next;else delete params.patient;window.history.replaceState({module:'veterinaria'},'',UrlStateService.href('veterinaria',params));};
  const loadBase=async({silent=false}={})=>{if(!silent)setLoading(true);setBaseError('');try{const [summary,patientResponse,professionalResponse,appointmentResponse]=await Promise.all([VeterinaryService.dashboard(),HealthVerticalService.patients({kind:'animal'}),HealthVerticalService.professionals(),HealthVerticalService.appointments({kind:'animal'})]);const pets=arrayData(patientResponse).filter((x)=>x.kind==='animal'&&x.active!==false);setDashboard(objectData(summary));setPatients(pets);setProfessionals(arrayData(professionalResponse));setAppointments(arrayData(appointmentResponse).filter((x)=>!x.patientKind||x.patientKind==='animal'));if(patientRef.current&&!pets.some((x)=>x.id===patientRef.current)){patientRef.current='';setSelectedPatientId('');}if(!patientRef.current&&pets.length){patientRef.current=pets[0].id;setSelectedPatientId(pets[0].id);updateUrl(tabRef.current,pets[0].id);}return true;}catch(error){reportVeterinaryError('workspace.loadBase',error);setBaseError(displayError(error));toast.error(displayError(error));return false;}finally{setLoading(false);}};
  const loadPatientData=async(patientId)=>{if(!patientId){setPatientDataError('');setEncounters([]);setPrescriptions([]);setConsents([]);setLabOrders([]);setLabResults([]);setStudies([]);setHospitalizations([]);setProcedures([]);setCommunications([]);return true;}setPatientDataError('');try{const [a,b,c,d,e,f,g,h,i]=await Promise.all([HealthVerticalService.encounters(patientId),HealthVerticalService.prescriptions(patientId),HealthVerticalService.consents(patientId),VeterinaryService.labOrders({patientId}),VeterinaryService.labResults({patientId}),VeterinaryService.studies({patientId}),VeterinaryService.hospitalizations({patientId}),VeterinaryService.procedures({patientId}),VeterinaryService.communications({patientId})]);setEncounters(arrayData(a));setPrescriptions(arrayData(b));setConsents(arrayData(c));setLabOrders(arrayData(d));setLabResults(arrayData(e));setStudies(arrayData(f));setHospitalizations(arrayData(g));setProcedures(arrayData(h));setCommunications(arrayData(i));return true;}catch(error){reportVeterinaryError('workspace.loadPatientData',error);setPatientDataError(displayError(error));toast.error(displayError(error));return false;}};
  useEffect(()=>{void loadBase();},[]); useEffect(()=>{void loadPatientData(selectedPatientId);},[selectedPatientId]);
  const changeTab=(_e,value)=>{tabRef.current=value;setTab(value);updateUrl(value,patientRef.current);}; const selectPatient=(id)=>{patientRef.current=id;setSelectedPatientId(id);tabRef.current='pacientes';setTab('pacientes');updateUrl('pacientes',id);};
  const openDialog=(name,defaults={})=>{setForm(defaults);setDialog(name);}; const closeDialog=()=>{if(!busy){setDialog('');setForm({});}};
  const applySoapTemplate=()=>{const consultationType=field('consultationType','problem');const template=resolveVeterinarySoapTemplate({species:selectedPatient?.species||'',consultationType});setForm((current)=>({...current,subjective:template.subjective,objective:template.objective,assessment:template.assessment,plan:template.plan,soapTemplateId:template.id,soapTemplateVersion:SOAP_TEMPLATE_VERSION}));toast.success(`Plantilla SOAP aplicada: ${template.label}`);};
  const guardedDialogClose=(_event,reason)=>{if(reason==='backdropClick'||reason==='escapeKeyDown')return;closeDialog();};
  const refreshAll=async()=>{const [baseOk,patientOk]=await Promise.all([loadBase({silent:true}),loadPatientData(selectedPatientId)]);if(baseOk&&patientOk)toast.success('Información actualizada.');};
  const partialDateSelected=(name)=>['year','month','day'].some((part)=>Boolean(field(`__${name}_${part}`)));
  const patientPayload=()=>{const birthDate=field('birthDate');if(partialDateSelected('birthDate')&&!birthDate)throw new Error('Completa día, mes y año de nacimiento o deja la fecha vacía.');return {kind:'animal',displayName:field('displayName'),species:field('species'),breed:field('breed'),color:field('color'),sex:field('sex'),birthDate:birthDate||null,microchip:field('microchip'),guardianName:field('guardianName'),guardianPhone:field('guardianPhone'),guardianEmail:field('guardianEmail'),allergies:field('allergies'),conditions:field('conditions'),notes:field('notes'),active:true};};
  const appointmentPayload=()=>({patientId:field('patientId',selectedPatientId),professionalId:field('professionalId')||null,startsAt:field('startsAt'),endsAt:field('endsAt'),type:field('type','consultation'),status:field('status','scheduled'),reason:field('reason'),channel:field('channel','onsite'),room:field('room'),notes:field('notes')});
  const validateAppointment=()=>{const p=appointmentPayload();if(!p.patientId)throw new Error('Selecciona la mascota.');if(!p.startsAt||!p.endsAt)throw new Error('Completa día, mes, año y hora de inicio y fin.');if(new Date(p.endsAt)<=new Date(p.startsAt))throw new Error('La hora de fin debe ser posterior al inicio.');if(!String(p.reason||'').trim())throw new Error('Indica el motivo de la cita.');return p;};
  const submit=async()=>{setBusy(true);const promise=(async()=>{switch(dialog){case'patient':if(field('_entityId'))await HealthVerticalService.updatePatient(field('_entityId'),patientPayload());else await HealthVerticalService.createPatient(patientPayload());break;case'professional':await HealthVerticalService.createProfessional({fullName:field('fullName'),specialty:field('specialty','Medicina veterinaria general'),licenseNumber:field('licenseNumber'),email:field('email'),phone:field('phone'),status:'active',schedule:{}});break;case'appointment':{const payload=validateAppointment();if(field('_entityId'))await HealthVerticalService.updateAppointment(field('_entityId'),payload);else await HealthVerticalService.createAppointment(payload);break;}case'encounter':await HealthVerticalService.createEncounter({patientId:selectedPatientId,professionalId:field('professionalId')||null,specialty:field('specialty','Medicina veterinaria general'),type:field('type','consultation'),subjective:field('subjective'),objective:field('objective'),assessment:field('assessment'),plan:field('plan'),diagnosisCodes:String(field('diagnosisCodes')).split(',').map((x)=>x.trim()).filter(Boolean),clinicalData:{soapTemplate:{templateId:field('soapTemplateId')||null,version:field('soapTemplateVersion')||null,species:selectedPatient?.species||null,consultationType:field('consultationType','problem')}},confidential:false,status:field('status','signed')});break;case'prescription':await HealthVerticalService.createPrescription({patientId:selectedPatientId,professionalId:field('professionalId')||null,medication:field('medication'),dose:field('dose'),frequency:field('frequency'),duration:field('duration'),instructions:field('instructions'),status:'active'});break;case'consent':await HealthVerticalService.createConsent({patientId:selectedPatientId,kind:field('kind'),status:field('status','pending'),signerName:field('signerName'),signedAt:field('status')==='signed'?new Date().toISOString():null,metadata:{notes:field('notes')}});break;case'labOrder':{const tests=String(field('tests')).split('\n').map((x)=>x.trim()).filter(Boolean).map((line)=>{const[testName,category='',unit='',min='',max='']=line.split('|').map((x)=>x.trim());return{testName,category:category||null,unit:unit||null,referenceMin:min===''?null:Number(min),referenceMax:max===''?null:Number(max)};});await VeterinaryService.createLabOrder({patientId:selectedPatientId,professionalId:field('professionalId')||null,priority:field('priority','routine'),laboratory:field('laboratory'),specimenType:field('specimenType'),fasting:Boolean(field('fasting')),notes:field('notes'),tests});break;}case'labResult':await VeterinaryService.createLabResult({labOrderId:field('labOrderId'),resultId:field('resultId')||null,testCode:field('testCode')||null,testName:field('testName'),category:field('category'),valueText:field('valueText'),valueNumeric:field('valueNumeric')===''?null:Number(field('valueNumeric')),unit:field('unit'),referenceMin:field('referenceMin')===''?null:Number(field('referenceMin')),referenceMax:field('referenceMax')===''?null:Number(field('referenceMax')),referenceText:field('referenceText'),notes:field('notes')});break;case'study':await VeterinaryService.createStudy({patientId:selectedPatientId,professionalId:field('professionalId')||null,kind:field('kind','xray'),title:field('title'),bodySite:field('bodySite'),status:field('status','ordered'),scheduledAt:field('scheduledAt')||null,performedAt:field('performedAt')||null,findings:field('findings'),impression:field('impression'),externalUrl:field('externalUrl')});break;case'hospitalization':await VeterinaryService.createHospitalization({patientId:selectedPatientId,professionalId:field('professionalId')||null,admittedAt:field('admittedAt')||null,ward:field('ward'),cage:field('cage'),reason:field('reason'),diagnosis:field('diagnosis'),status:'admitted',carePlan:{fluids:field('fluids'),feeding:field('feeding'),monitoring:field('monitoring')}});break;case'observation':await VeterinaryService.createObservation({hospitalizationId:field('hospitalizationId'),professionalId:field('professionalId')||null,type:field('type','note'),values:{temperature:field('temperature'),heartRate:field('heartRate'),respiratoryRate:field('respiratoryRate'),weight:field('weight')},note:field('note')});break;case'procedure':await VeterinaryService.createProcedure({patientId:selectedPatientId,professionalId:field('professionalId')||null,name:field('name'),kind:field('kind','procedure'),status:field('status','planned'),scheduledAt:field('scheduledAt')||null,performedAt:field('performedAt')||null,anesthesia:field('anesthesia'),notes:field('notes'),outcome:field('outcome')});break;default:throw new Error('Operación no reconocida.');}await loadBase({silent:true});await loadPatientData(patientRef.current||selectedPatientId);})();toast.promise(promise,{loading:'Guardando…',success:'Registro guardado correctamente.',error:displayError});try{await promise;setActionError('');closeDialog();}catch(error){reportVeterinaryError('workspace.submit',error);setActionError(displayError(error));}finally{setBusy(false);}};
  const editPatient=()=>selectedPatient&&openDialog('patient',{...selectedPatient,_entityId:selectedPatient.id,birthDate:selectedPatient.birthDate?String(selectedPatient.birthDate).slice(0,10):''});
  const archivePatient=async()=>{if(!selectedPatient||!window.confirm(`¿Archivar el expediente de ${selectedPatient.displayName}? El historial clínico se conservará para auditoría.`))return;try{await HealthVerticalService.archivePatient(selectedPatient.id);patientRef.current='';setSelectedPatientId('');await loadBase({silent:true});toast.success('Mascota archivada.');}catch(error){reportVeterinaryError('workspace.archivePatient',error);setActionError(displayError(error));toast.error(displayError(error));}};
  const editAppointment=(item)=>openDialog('appointment',{...item,_entityId:item.id,startsAt:localDateTimeFromIso(item.startsAt),endsAt:localDateTimeFromIso(item.endsAt)});
  const removeAppointment=async(item)=>{const name=item.patientName||patients.find((x)=>x.id===item.patientId)?.displayName||'esta mascota';if(!window.confirm(`¿Eliminar la cita de ${name}? Si ya tiene trazabilidad clínica, se archivará como cancelada.`))return;try{const result=await HealthVerticalService.deleteAppointment(item.id);await loadBase({silent:true});toast.success(result?.archived?'Cita archivada por trazabilidad.':'Cita eliminada.');}catch(error){reportVeterinaryError('workspace.removeAppointment',error);setActionError(displayError(error));toast.error(displayError(error));}};
  const notifyAppointment=async(appointment,channel)=>{const patient=patients.find((x)=>x.id===appointment.patientId)||selectedPatient;if(!patient)return toast.error('No se encontró la mascota.');const message=`Hola ${patient.guardianName||'tutor'}, recordatorio de la cita de ${patient.displayName} para ${compactDate(appointment.startsAt)}. Motivo: ${appointment.reason||'consulta veterinaria'}.`;const recipient=channel==='whatsapp'?phoneDigits(patient.guardianPhone):patient.guardianEmail;if(!recipient)return toast.error(channel==='whatsapp'?'El tutor no tiene teléfono registrado.':'El tutor no tiene correo registrado.');try{await VeterinaryService.createCommunication({patientId:patient.id,appointmentId:appointment.id,channel,event:'appointment_reminder',recipient,status:channel==='whatsapp'?'sent':'queued',sentAt:channel==='whatsapp'?new Date().toISOString():null,payload:{message,appointmentAt:appointment.startsAt}});if(channel==='whatsapp')window.open(`https://wa.me/${recipient}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');else window.location.href=`mailto:${encodeURIComponent(recipient)}?subject=${encodeURIComponent(`Cita veterinaria de ${patient.displayName}`)}&body=${encodeURIComponent(message)}`;toast.success(channel==='whatsapp'?'WhatsApp preparado.':'Correo preparado.');await loadPatientData(selectedPatientId);}catch(error){reportVeterinaryError('workspace.notifyAppointment',error);setActionError(displayError(error));toast.error(displayError(error));}};
  const updateAppointment=async(item,status)=>{const task=VeterinaryService.updateAppointmentStatus(item.id,{status});toast.promise(task,{loading:'Actualizando cita…',success:'Estado actualizado.',error:displayError});try{await task;setActionError('');await loadBase({silent:true});}catch(error){reportVeterinaryError('workspace.updateAppointment',error);setActionError(displayError(error));}};
  const filteredPatients=patients.filter((x)=>!search||[x.displayName,x.guardianName,x.microchip,x.species,x.breed].some((v)=>String(v||'').toLowerCase().includes(search.toLowerCase())));
  const availableLabTests=labResults.filter((item)=>item.labOrderId===field('labOrderId')&&item.valueNumeric===null&&!String(item.valueText||'').trim());
  const selectLabTest=(resultId)=>{const test=labResults.find((item)=>item.id===resultId);if(!test)return;setForm((current)=>({...current,resultId:test.id,testCode:test.testCode||'',testName:test.testName||'',category:test.category||'',unit:test.unit||'',referenceMin:test.referenceMin??'',referenceMax:test.referenceMax??'',referenceText:test.referenceText||''}));};

  const patientSelect=<TextField select label="Mascota *" value={field('patientId',selectedPatientId)} onChange={setField('patientId')} SelectProps={{renderValue:(id)=>{const p=patients.find((x)=>x.id===id);return p?<EntityLabel primary={p.displayName} secondary={p.guardianName||'Sin tutor'} id={p.id}/>:<Typography variant="body2">Seleccionar mascota</Typography>;}}}><MenuItem value="">Seleccionar mascota</MenuItem>{patients.map((p)=><MenuItem key={p.id} value={p.id}><EntityLabel primary={p.displayName} secondary={`${p.species||'Mascota'} · ${p.guardianName||'Sin tutor'}`} id={p.id}/></MenuItem>)}</TextField>;
  const professionalSelect=<TextField select label="Profesional" value={field('professionalId')} onChange={setField('professionalId')} SelectProps={{renderValue:(id)=>{if(!id)return <Typography variant="body2" color="text.secondary">Por asignar</Typography>;const p=professionals.find((x)=>x.id===id);return p?<EntityLabel primary={p.fullName} secondary={p.specialty} id={p.id}/>:<Typography variant="body2">Por asignar</Typography>;}}}><MenuItem value="">Por asignar</MenuItem>{professionals.map((p)=><MenuItem key={p.id} value={p.id}><EntityLabel primary={p.fullName} secondary={p.specialty} id={p.id}/></MenuItem>)}</TextField>;
  const DateParts=({name,label,withTime=false,yearMin=1900,yearMax=new Date().getFullYear()+3})=>{const raw=String(field(name)||'');const [datePart,timePart='09:00']=raw.split('T');const [savedY='',savedM='',savedD='']=datePart.split('-');const key=(part)=>`__${name}_${part}`;const y=String(field(key('year'),savedY)||'');const m=String(field(key('month'),savedM)||'');const d=String(field(key('day'),savedD)||'');const t=String(field(key('time'),timePart||'09:00')||'09:00');const update=(part,value)=>setForm((current)=>{const next={year:String(current[key('year')]??savedY??''),month:String(current[key('month')]??savedM??''),day:String(current[key('day')]??savedD??''),time:String(current[key('time')]??timePart??'09:00')};next[part]=String(value);const complete=next.year&&next.month&&next.day?`${next.year.padStart(4,'0')}-${next.month.padStart(2,'0')}-${next.day.padStart(2,'0')}${withTime?`T${next.time||'09:00'}`:''}`:'';return {...current,[key(part)]:String(value),[name]:complete};});return <Box sx={{border:'1px solid',borderColor:'divider',borderRadius:1,p:1}}><Typography variant="caption" color="text.secondary" sx={{display:'block',mb:.7,fontWeight:600}}>{label}</Typography><Box sx={{display:'grid',gridTemplateColumns:withTime?{xs:'1fr 1.3fr',sm:'72px 1.25fr 86px 110px'}:{xs:'1fr 1.3fr 1fr',sm:'72px 1.35fr 90px'},gap:.7}}><TextField select label="Día" value={d?Number(d):''} onChange={(e)=>update('day',e.target.value)}>{Array.from({length:31},(_,i)=>i+1).map((v)=><MenuItem key={v} value={v}>{v}</MenuItem>)}</TextField><TextField select label="Mes" value={m?Number(m):''} onChange={(e)=>update('month',e.target.value)}>{MONTHS.map((v,i)=><MenuItem key={v} value={i+1}>{v}</MenuItem>)}</TextField><TextField label="Año" type="number" inputProps={{min:yearMin,max:yearMax,inputMode:'numeric'}} value={y} onChange={(e)=>update('year',e.target.value)}/>{withTime&&<TextField label="Hora" type="time" value={t} onChange={(e)=>update('time',e.target.value)}/>}</Box></Box>;};

  const renderOverview=()=> <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'1.25fr .75fr'},gap:1.5}}><SectionCard title="Agenda de hoy" subtitle="Confirmación y seguimiento desde la misma vista" action={<Button startIcon={<Icon name="fa-plus"/>} onClick={()=>openDialog('appointment',{patientId:selectedPatientId,startsAt:localDateTime(60),endsAt:localDateTime(90),channel:'onsite'})}>Nueva cita</Button>}>{appointments.length?<Stack gap={.8}>{appointments.slice(0,8).map((item)=><Paper key={item.id} variant="outlined" sx={{p:1,display:'grid',gridTemplateColumns:{xs:'1fr auto',sm:'70px minmax(0,1fr) auto'},gap:1,alignItems:'center'}}><Box><Typography variant="subtitle2">{new Date(item.startsAt).toLocaleTimeString('es-VE',{hour:'2-digit',minute:'2-digit'})}</Typography><Typography variant="caption">{onlyDate(item.startsAt)}</Typography></Box><Box sx={{minWidth:0}}><Typography variant="subtitle2" noWrap>{item.patientName||patients.find((p)=>p.id===item.patientId)?.displayName||'Mascota'}</Typography><Typography variant="caption" color="text.secondary" noWrap>{item.reason||'Consulta'} · {item.professionalName||'Sin asignar'}</Typography></Box><Stack direction="row" gap={.3}><Tooltip title="Editar"><IconButton size="small" onClick={()=>editAppointment(item)}><Icon name="fa-pen"/></IconButton></Tooltip><Tooltip title="WhatsApp"><IconButton size="small" color="success" onClick={()=>notifyAppointment(item,'whatsapp')}><i className="fa-brands fa-whatsapp"/></IconButton></Tooltip></Stack></Paper>)}</Stack>:<EmptyState icon="fa-calendar-check" title="Agenda libre" text="No hay citas próximas registradas."/>}</SectionCard><Stack gap={1.5}><SectionCard title="Alertas clínicas" subtitle="Prioridades de los últimos 30 días"><Stack gap={.8}><Alert severity={Number(dashboard.abnormalResults)?'warning':'success'}><b>{dashboard.abnormalResults||0}</b> resultados fuera de rango</Alert><Alert severity={Number(dashboard.pendingLabOrders)?'info':'success'}><b>{dashboard.pendingLabOrders||0}</b> órdenes pendientes</Alert><Alert severity={Number(dashboard.vaccinesDue)?'warning':'success'}><b>{dashboard.vaccinesDue||0}</b> vacunas próximas</Alert></Stack></SectionCard><SectionCard title="Acciones rápidas"><Box sx={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:.8}}><Button variant="outlined" disabled={!selectedPatient} onClick={()=>{setTab('historia');updateUrl('historia',selectedPatientId);}}>Historia</Button><Button variant="outlined" disabled={!selectedPatient} onClick={()=>openDialog('labOrder',{priority:'routine',tests:'Hemograma completo|Hematología||||\nBioquímica básica|Bioquímica||||'})}>Laboratorio</Button><Button variant="outlined" disabled={!selectedPatient} onClick={()=>openDialog('hospitalization',{admittedAt:localDateTime()})}>Hospitalizar</Button><Button variant="outlined" disabled={!selectedPatient} onClick={()=>openDialog('procedure',{status:'planned',scheduledAt:localDateTime(60)})}>Procedimiento</Button></Box></SectionCard></Stack></Box>;
  const renderPatients=()=> <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',md:'300px minmax(0,1fr)'},gap:1.5}}><SectionCard title="Mascotas" subtitle={`${patients.length} expedientes`} action={<Button startIcon={<Icon name="fa-plus"/>} onClick={()=>openDialog('patient')}>Nueva</Button>}><TextField placeholder="Buscar mascota, tutor o microchip" value={search} onChange={(e)=>setSearch(e.target.value)} InputProps={{startAdornment:<InputAdornment position="start"><Icon name="fa-magnifying-glass"/></InputAdornment>}}/><List dense sx={{mt:1,maxHeight:520,overflow:'auto'}}>{filteredPatients.map((item)=><ListItemButton key={item.id} selected={item.id===selectedPatientId} onClick={()=>selectPatient(item.id)} sx={{borderRadius:1,mb:.4}}><ListItemAvatar><Avatar variant="rounded" src={item.photoUrl||''} sx={{width:34,height:34,borderRadius:'8px',bgcolor:'primary.main'}}>{item.displayName?.slice(0,1)}</Avatar></ListItemAvatar><ListItemText primary={item.displayName} secondary={`${item.species||'Especie'} · ${item.breed||'Sin raza'} · ${item.guardianName||'Sin tutor'} · #${shortCode(item.id)}`} primaryTypographyProps={{fontSize:'.8125rem',fontWeight:600}} secondaryTypographyProps={{fontSize:'.6875rem',noWrap:true}}/></ListItemButton>)}</List></SectionCard>{selectedPatient?<Stack gap={1.5}><SectionCard title={selectedPatient.displayName} subtitle={`${selectedPatient.species||'Mascota'} · ${selectedPatient.breed||'Sin raza'} · expediente #${shortCode(selectedPatient.id)}`} action={<Stack direction="row" gap={.5} flexWrap="wrap"><Button variant="outlined" onClick={editPatient} startIcon={<Icon name="fa-pen"/>}>Editar</Button><Button variant="outlined" color="error" onClick={archivePatient} startIcon={<Icon name="fa-box-archive"/>}>Archivar</Button><Button variant="outlined" startIcon={<i className="fa-brands fa-whatsapp"/>} onClick={()=>{const p=phoneDigits(selectedPatient.guardianPhone);if(p)window.open(`https://wa.me/${p}`,'_blank');else toast.error('No hay teléfono registrado.');}}>Tutor</Button><Button startIcon={<Icon name="fa-calendar-plus"/>} onClick={()=>openDialog('appointment',{patientId:selectedPatientId,startsAt:localDateTime(60),endsAt:localDateTime(90),channel:'onsite'})}>Agendar</Button></Stack>}><Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr 1fr',lg:'repeat(4,1fr)'},gap:1}}>{[['Tutor',selectedPatient.guardianName],['Teléfono',selectedPatient.guardianPhone],['Microchip',selectedPatient.microchip],['Nacimiento',onlyDate(selectedPatient.birthDate)],['Sexo',selectedPatient.sex],['Color',selectedPatient.color],['Alergias',selectedPatient.allergies],['Condiciones',selectedPatient.conditions]].map(([label,value])=><Paper key={label} variant="outlined" sx={{p:1}}><Typography variant="caption" color="text.secondary">{label}</Typography><Typography variant="subtitle2">{value||'—'}</Typography></Paper>)}</Box></SectionCard><SectionCard title="Resumen del expediente"><Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr 1fr',lg:'repeat(4,1fr)'},gap:1}}><Metric icon="fa-file-waveform" label="Consultas" value={encounters.length}/><Metric icon="fa-flask-vial" label="Laboratorios" value={labOrders.length} tone="secondary"/><Metric icon="fa-x-ray" label="Estudios" value={studies.length} tone="warning"/><Metric icon="fa-house-medical" label="Hospitalizaciones" value={hospitalizations.length} tone="error"/></Box></SectionCard></Stack>:<SectionCard title="Expediente"><EmptyState icon="fa-paw" title="Selecciona una mascota"/></SectionCard>}</Box>;
  const renderAgenda=()=> <SectionCard title="Agenda veterinaria" subtitle="Citas, confirmaciones, llegada, consulta y cierre" action={<Button startIcon={<Icon name="fa-plus"/>} onClick={()=>openDialog('appointment',{patientId:selectedPatientId,startsAt:localDateTime(60),endsAt:localDateTime(90),channel:'onsite'})}>Nueva cita</Button>}>{appointments.length?<TableContainer><Table stickyHeader><TableHead><TableRow><TableCell>Fecha</TableCell><TableCell>Mascota / tutor</TableCell><TableCell>Profesional</TableCell><TableCell>Motivo</TableCell><TableCell>Estado</TableCell><TableCell align="right">Acciones</TableCell></TableRow></TableHead><TableBody>{appointments.map((item)=>{const p=patients.find((x)=>x.id===item.patientId);return <TableRow key={item.id} hover><TableCell>{compactDate(item.startsAt)}</TableCell><TableCell><b>{item.patientName||p?.displayName||'Mascota'}</b><br/><Typography variant="caption">{p?.guardianName||'Sin tutor'} · #{shortCode(item.patientId)}</Typography></TableCell><TableCell>{item.professionalName||'Por asignar'}</TableCell><TableCell>{item.reason||'Consulta'}</TableCell><TableCell><StatusChip value={item.status}/></TableCell><TableCell align="right"><Stack direction="row" justifyContent="flex-end" gap={.2}><Tooltip title="Editar"><IconButton size="small" onClick={()=>editAppointment(item)}><Icon name="fa-pen"/></IconButton></Tooltip><Tooltip title="Confirmar"><IconButton size="small" onClick={()=>updateAppointment(item,'confirmed')}><Icon name="fa-check"/></IconButton></Tooltip><Tooltip title="Completar"><IconButton size="small" onClick={()=>updateAppointment(item,'completed')}><Icon name="fa-flag-checkered"/></IconButton></Tooltip><Tooltip title="WhatsApp"><IconButton size="small" color="success" onClick={()=>notifyAppointment(item,'whatsapp')}><i className="fa-brands fa-whatsapp"/></IconButton></Tooltip><Tooltip title="Eliminar"><IconButton size="small" color="error" onClick={()=>removeAppointment(item)}><Icon name="fa-trash"/></IconButton></Tooltip></Stack></TableCell></TableRow>;})}</TableBody></Table></TableContainer>:<EmptyState icon="fa-calendar" title="Sin citas" text="Agrega la primera cita veterinaria."/>}</SectionCard>;
  const renderHistory=()=>!selectedPatient?<SectionCard title="Historia clínica"><EmptyState icon="fa-file-waveform" title="Selecciona una mascota"/></SectionCard>:<Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'minmax(0,1.4fr) minmax(260px,.6fr)'},gap:1.5}}><SectionCard title={`Historia clínica · ${selectedPatient.displayName}`} subtitle="Notas SOAP, diagnósticos, plan y evolución" action={<Button startIcon={<Icon name="fa-plus"/>} onClick={()=>openDialog('encounter',{specialty:'Medicina veterinaria general',status:'signed',consultationType:'problem'})}>Nueva consulta</Button>}>{encounters.length?<Stack gap={1}>{encounters.map((item)=><Paper key={item.id} variant="outlined" sx={{p:1.2}}><Stack direction="row" justifyContent="space-between"><Box><Typography variant="subtitle2">{item.specialty}</Typography><Typography variant="caption">{compactDate(item.createdAt)} · {item.professionalName||'Profesional'}</Typography></Box><StatusChip value={item.status}/></Stack><Divider sx={{my:1}}/>{[['Motivo / subjetivo',item.subjective],['Hallazgos / objetivo',item.objective],['Evaluación / diagnóstico',item.assessment],['Plan y seguimiento',item.plan]].filter(([,v])=>v).map(([l,v])=><Box key={l} mb={.7}><Typography variant="caption" color="text.secondary" sx={{fontWeight:600}}>{l}</Typography><Typography variant="body2">{v}</Typography></Box>)}</Paper>)}</Stack>:<EmptyState icon="fa-file-medical" title="Sin consultas registradas"/>}</SectionCard><Stack gap={1.5}><SectionCard title="Tratamientos" action={<Button variant="outlined" onClick={()=>openDialog('prescription')}>Prescribir</Button>}>{prescriptions.length?prescriptions.slice(0,8).map((x)=><Paper key={x.id} variant="outlined" sx={{p:1,mb:.7}}><Typography variant="subtitle2">{x.medication}</Typography><Typography variant="caption">{[x.dose,x.frequency,x.duration].filter(Boolean).join(' · ')}</Typography></Paper>):<EmptyState icon="fa-pills" title="Sin prescripciones"/>}</SectionCard><SectionCard title="Consentimientos" action={<Button variant="outlined" onClick={()=>openDialog('consent',{status:'pending'})}>Nuevo</Button>}>{consents.length?consents.slice(0,8).map((x)=><Paper key={x.id} variant="outlined" sx={{p:1,mb:.7,display:'flex',justifyContent:'space-between'}}><Box><Typography variant="subtitle2">{x.kind}</Typography><Typography variant="caption">{x.signerName||'Pendiente de firma'}</Typography></Box><StatusChip value={x.status}/></Paper>):<EmptyState icon="fa-file-signature" title="Sin consentimientos"/>}</SectionCard></Stack></Box>;
  const renderLabs=()=>!selectedPatient?<SectionCard title="Laboratorio"><EmptyState icon="fa-flask-vial" title="Selecciona una mascota"/></SectionCard>:<Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'minmax(0,.9fr) minmax(0,1.1fr)'},gap:1.5}}><SectionCard title="Órdenes de laboratorio" subtitle={selectedPatient.displayName} action={<Button onClick={()=>openDialog('labOrder',{priority:'routine',tests:'Hemograma completo|Hematología||||\nBioquímica básica|Bioquímica||||'})}>Nueva orden</Button>}>{labOrders.length?<Stack gap={.8}>{labOrders.map((x)=><Paper key={x.id} variant="outlined" sx={{p:1}}><Stack direction="row" justifyContent="space-between"><Box><Typography variant="subtitle2">{x.orderNumber}</Typography><Typography variant="caption">{compactDate(x.orderedAt)} · {x.laboratory||'Laboratorio interno'}</Typography></Box><StatusChip value={x.status}/></Stack><Stack direction="row" gap={.5} mt={.8}><Chip label={`${x.resultCount||0} pruebas`} variant="outlined"/><Chip label={`${x.abnormalCount||0} alertas`} color={Number(x.abnormalCount)?'warning':'success'}/><Button variant="text" disabled={x.status==='completed'} onClick={()=>openDialog('labResult',{labOrderId:x.id})}>{x.status==='completed'?'Completa':'Capturar resultado'}</Button></Stack></Paper>)}</Stack>:<EmptyState icon="fa-flask" title="Sin órdenes"/>}</SectionCard><SectionCard title="Resultados" subtitle="Valores y rangos de referencia">{labResults.length?<TableContainer><Table><TableHead><TableRow><TableCell>Prueba</TableCell><TableCell>Resultado</TableCell><TableCell>Referencia</TableCell><TableCell>Bandera</TableCell><TableCell>Fecha</TableCell></TableRow></TableHead><TableBody>{labResults.map((x)=><TableRow key={x.id}><TableCell><b>{x.testName}</b><br/><Typography variant="caption">{x.category||'General'}</Typography></TableCell><TableCell>{x.valueNumeric??x.valueText??'Pendiente'} {x.unit||''}</TableCell><TableCell>{x.referenceText||[x.referenceMin,x.referenceMax].filter((v)=>v!==null&&v!==undefined).join(' – ')||'—'}</TableCell><TableCell><StatusChip value={x.flag}/></TableCell><TableCell>{onlyDate(x.observedAt)}</TableCell></TableRow>)}</TableBody></Table></TableContainer>:<EmptyState icon="fa-chart-line" title="Sin resultados"/>}</SectionCard></Box>;
  const renderStudies=()=> <SectionCard title="Estudios diagnósticos" subtitle="Radiología, ecografía, ECG, patología y otros" action={<Button disabled={!selectedPatient} onClick={()=>openDialog('study',{kind:'xray',status:'ordered',scheduledAt:localDateTime(60)})}>Nuevo estudio</Button>}>{studies.length?<TableContainer><Table><TableHead><TableRow><TableCell>Estudio</TableCell><TableCell>Zona</TableCell><TableCell>Fecha</TableCell><TableCell>Hallazgos</TableCell><TableCell>Impresión</TableCell><TableCell>Estado</TableCell></TableRow></TableHead><TableBody>{studies.map((x)=><TableRow key={x.id}><TableCell><b>{x.title}</b><br/><Typography variant="caption">{x.kind}</Typography></TableCell><TableCell>{x.bodySite||'—'}</TableCell><TableCell>{compactDate(x.performedAt||x.scheduledAt)}</TableCell><TableCell>{x.findings||'Pendiente'}</TableCell><TableCell>{x.impression||'Pendiente'}</TableCell><TableCell><StatusChip value={x.status}/></TableCell></TableRow>)}</TableBody></Table></TableContainer>:<EmptyState icon="fa-x-ray" title="Sin estudios"/>}</SectionCard>;
  const renderHospital=()=> <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'minmax(0,1fr) 320px'},gap:1.5}}><SectionCard title="Hospitalización" subtitle="Admisiones, jaulas, plan de cuidados y alta" action={<Button disabled={!selectedPatient} onClick={()=>openDialog('hospitalization',{admittedAt:localDateTime()})}>Nueva admisión</Button>}>{hospitalizations.length?<Stack gap={.8}>{hospitalizations.map((x)=><Paper key={x.id} variant="outlined" sx={{p:1.1}}><Stack direction="row" justifyContent="space-between"><Box><Typography variant="subtitle2">{x.admissionNumber}</Typography><Typography variant="caption">{x.ward||'Área general'} · Jaula {x.cage||'—'} · {compactDate(x.admittedAt)}</Typography></Box><StatusChip value={x.status}/></Stack><Typography variant="body2" mt={.8}><b>Motivo:</b> {x.reason}</Typography><Typography variant="body2"><b>Diagnóstico:</b> {x.diagnosis||'En evaluación'}</Typography><Stack direction="row" gap={.6} mt={1}><Button variant="outlined" onClick={()=>openDialog('observation',{hospitalizationId:x.id,type:'vitals'})}>Registrar control</Button>{!['discharged','cancelled'].includes(x.status)&&<Button color="success" variant="outlined" onClick={async()=>{await VeterinaryService.updateHospitalizationStatus(x.id,{status:'discharged'});await loadPatientData(selectedPatientId);toast.success('Alta registrada.');}}>Dar alta</Button>}</Stack></Paper>)}</Stack>:<EmptyState icon="fa-house-medical" title="Sin hospitalizaciones"/>}</SectionCard><SectionCard title="Monitoreo activo"><Metric icon="fa-bed-pulse" label="Hospitalizados" value={dashboard.hospitalized||0} tone="error"/><Alert severity="info" sx={{mt:1}}>Registra signos vitales y cuidados desde cada admisión.</Alert></SectionCard></Box>;
  const renderProcedures=()=> <SectionCard title="Procedimientos y cirugías" subtitle="Planificación, anestesia, ejecución y resultado" action={<Button disabled={!selectedPatient} onClick={()=>openDialog('procedure',{status:'planned',scheduledAt:localDateTime(60)})}>Nuevo procedimiento</Button>}>{procedures.length?<TableContainer><Table><TableHead><TableRow><TableCell>Procedimiento</TableCell><TableCell>Tipo</TableCell><TableCell>Programado</TableCell><TableCell>Anestesia</TableCell><TableCell>Resultado</TableCell><TableCell>Estado</TableCell></TableRow></TableHead><TableBody>{procedures.map((x)=><TableRow key={x.id}><TableCell><b>{x.name}</b></TableCell><TableCell>{x.kind}</TableCell><TableCell>{compactDate(x.performedAt||x.scheduledAt)}</TableCell><TableCell>{x.anesthesia||'—'}</TableCell><TableCell>{x.outcome||'Pendiente'}</TableCell><TableCell><StatusChip value={x.status}/></TableCell></TableRow>)}</TableBody></Table></TableContainer>:<EmptyState icon="fa-stethoscope" title="Sin procedimientos"/>}</SectionCard>;
  const renderCommunications=()=> <SectionCard title="Seguimiento multicanal" subtitle="WhatsApp, correo, SMS y trazabilidad por mascota" action={<Button variant="outlined" data-route="mensajes">Editar plantillas</Button>}>{communications.length?<TableContainer><Table><TableHead><TableRow><TableCell>Fecha</TableCell><TableCell>Canal</TableCell><TableCell>Evento</TableCell><TableCell>Destinatario</TableCell><TableCell>Estado</TableCell></TableRow></TableHead><TableBody>{communications.map((x)=><TableRow key={x.id}><TableCell>{compactDate(x.createdAt)}</TableCell><TableCell>{x.channel}</TableCell><TableCell>{x.event.replaceAll('_',' ')}</TableCell><TableCell>{x.recipient}</TableCell><TableCell><StatusChip value={x.status}/></TableCell></TableRow>)}</TableBody></Table></TableContainer>:<EmptyState icon="fa-message" title="Sin comunicaciones"/>}</SectionCard>;
  const renderTab=()=>({resumen:renderOverview,pacientes:renderPatients,agenda:renderAgenda,historia:renderHistory,laboratorio:renderLabs,estudios:renderStudies,hospitalizacion:renderHospital,procedimientos:renderProcedures,comunicaciones:renderCommunications}[tab]||renderOverview)();
  const dialogTitle=({patient:field('_entityId')?'Editar mascota':'Nueva mascota',professional:'Nuevo profesional',appointment:field('_entityId')?'Editar cita':'Nueva cita',encounter:'Nueva consulta clínica',prescription:'Nueva prescripción',consent:'Nuevo consentimiento',labOrder:'Nueva orden de laboratorio',labResult:'Registrar resultado',study:'Nuevo estudio diagnóstico',hospitalization:'Nueva hospitalización',observation:'Control de hospitalización',procedure:'Nuevo procedimiento'})[dialog]||'Nuevo registro';
  const renderDialogFields=()=>{switch(dialog){case'patient':return <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',sm:'1fr 1fr'},gap:1.2}}><TextField label="Nombre de la mascota *" value={field('displayName')} onChange={setField('displayName')}/><TextField label="Especie *" value={field('species')} onChange={setField('species')}/><TextField label="Raza" value={field('breed')} onChange={setField('breed')}/><TextField label="Color" value={field('color')} onChange={setField('color')}/><TextField select label="Sexo" value={field('sex')} onChange={setField('sex')}><MenuItem value="">Sin indicar</MenuItem><MenuItem value="male">Macho</MenuItem><MenuItem value="female">Hembra</MenuItem></TextField><DateParts name="birthDate" label="Nacimiento" yearMin={1950} yearMax={new Date().getFullYear()}/><TextField label="Microchip" value={field('microchip')} onChange={setField('microchip')}/><TextField label="Tutor *" value={field('guardianName')} onChange={setField('guardianName')}/><TextField label="Teléfono tutor" value={field('guardianPhone')} onChange={setField('guardianPhone')}/><TextField label="Correo tutor" type="email" value={field('guardianEmail')} onChange={setField('guardianEmail')}/><TextField label="Alergias" multiline minRows={2} value={field('allergies')} onChange={setField('allergies')}/><TextField label="Condiciones / antecedentes" multiline minRows={2} value={field('conditions')} onChange={setField('conditions')}/><TextField label="Notas" multiline minRows={2} value={field('notes')} onChange={setField('notes')} sx={{gridColumn:'1/-1'}}/></Box>;case'professional':return <Stack gap={1.2}><TextField label="Nombre completo *" value={field('fullName')} onChange={setField('fullName')}/><TextField select label="Especialidad" value={field('specialty','Medicina veterinaria general')} onChange={setField('specialty')}>{['Medicina veterinaria general','Cirugía veterinaria','Dermatología veterinaria','Cardiología veterinaria','Diagnóstico por imágenes','Anestesiología','Hospitalización','Laboratorio clínico','Odontología veterinaria'].map((x)=><MenuItem key={x} value={x}>{x}</MenuItem>)}</TextField><TextField label="Matrícula / licencia" value={field('licenseNumber')} onChange={setField('licenseNumber')}/><TextField label="Correo" value={field('email')} onChange={setField('email')}/><TextField label="Teléfono" value={field('phone')} onChange={setField('phone')}/></Stack>;case'appointment':return <Stack gap={1.2}>{patientSelect}{professionalSelect}<Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',md:'1fr 1fr'},gap:1}}><DateParts name="startsAt" label="Inicio" withTime yearMin={new Date().getFullYear()-1}/><DateParts name="endsAt" label="Fin" withTime yearMin={new Date().getFullYear()-1}/></Box><TextField label="Motivo *" value={field('reason')} onChange={setField('reason')}/><TextField select label="Canal" value={field('channel','onsite')} onChange={setField('channel')}><MenuItem value="onsite">En clínica</MenuItem><MenuItem value="home_visit">Domicilio</MenuItem><MenuItem value="telemedicine">Teleconsulta</MenuItem></TextField><TextField label="Consultorio / sala" value={field('room')} onChange={setField('room')}/><TextField label="Notas" multiline minRows={2} value={field('notes')} onChange={setField('notes')}/></Stack>;case'encounter':return <Stack gap={1.1}>{professionalSelect}<Stack direction={{xs:'column',sm:'row'}} gap={1} alignItems={{sm:'center'}}><TextField select fullWidth label="Tipo de consulta" value={field('consultationType','problem')} onChange={setField('consultationType')}>{veterinaryConsultationTypes.map((item)=><MenuItem key={item.value} value={item.value}>{item.label}</MenuItem>)}</TextField><Button variant="outlined" onClick={applySoapTemplate} sx={{minHeight:40,whiteSpace:'nowrap'}}>Aplicar plantilla</Button></Stack><Typography variant="caption" color="text.secondary">Plantilla SOAP por especie/consulta. El contenido prellenado es editable y no constituye diagnóstico automático.</Typography><TextField label="Motivo / subjetivo" multiline minRows={2} value={field('subjective')} onChange={setField('subjective')}/><TextField label="Hallazgos / objetivo" multiline minRows={2} value={field('objective')} onChange={setField('objective')}/><TextField label="Evaluación / diagnóstico" multiline minRows={2} value={field('assessment')} onChange={setField('assessment')}/><TextField label="Plan / seguimiento" multiline minRows={2} value={field('plan')} onChange={setField('plan')}/></Stack>;case'prescription':return <Stack gap={1.1}>{professionalSelect}<TextField label="Medicamento *" value={field('medication')} onChange={setField('medication')}/><TextField label="Dosis" value={field('dose')} onChange={setField('dose')}/><TextField label="Frecuencia" value={field('frequency')} onChange={setField('frequency')}/><TextField label="Duración" value={field('duration')} onChange={setField('duration')}/><TextField label="Indicaciones" multiline minRows={3} value={field('instructions')} onChange={setField('instructions')}/></Stack>;case'consent':return <Stack gap={1.1}><TextField label="Tipo de consentimiento *" value={field('kind')} onChange={setField('kind')}/><TextField select label="Estado" value={field('status','pending')} onChange={setField('status')}><MenuItem value="pending">Pendiente</MenuItem><MenuItem value="signed">Firmado</MenuItem></TextField><TextField label="Firmante" value={field('signerName')} onChange={setField('signerName')}/><TextField label="Notas" multiline minRows={3} value={field('notes')} onChange={setField('notes')}/></Stack>;case'labOrder':return <Stack gap={1.1}>{professionalSelect}<TextField select label="Prioridad" value={field('priority','routine')} onChange={setField('priority')}><MenuItem value="routine">Rutina</MenuItem><MenuItem value="urgent">Urgente</MenuItem><MenuItem value="stat">STAT</MenuItem></TextField><TextField label="Laboratorio" value={field('laboratory')} onChange={setField('laboratory')}/><TextField label="Tipo de muestra" value={field('specimenType')} onChange={setField('specimenType')}/><TextField label="Pruebas — Nombre|Categoría|Unidad|Mín|Máx" multiline minRows={5} value={field('tests')} onChange={setField('tests')}/><TextField label="Notas" multiline minRows={2} value={field('notes')} onChange={setField('notes')}/></Stack>;case'labResult':return <Stack gap={1.1}><TextField select label="Orden *" value={field('labOrderId')} onChange={(e)=>{setForm((current)=>({...current,labOrderId:e.target.value,resultId:'',testCode:'',testName:'',category:'',unit:'',referenceMin:'',referenceMax:'',referenceText:''}));}}>{labOrders.map((x)=><MenuItem key={x.id} value={x.id}>{x.orderNumber}</MenuItem>)}</TextField><TextField select label="Prueba ordenada" value={field('resultId')} onChange={(e)=>selectLabTest(e.target.value)}>{availableLabTests.length?availableLabTests.map((x)=><MenuItem key={x.id} value={x.id}>{x.testName}{x.unit?` · ${x.unit}`:''}</MenuItem>):<MenuItem value="" disabled>Sin pruebas pendientes</MenuItem>}</TextField><TextField label="Prueba" value={field('testName')} disabled/><TextField label="Valor numérico" type="number" value={field('valueNumeric')} onChange={setField('valueNumeric')}/><TextField label="Valor textual" value={field('valueText')} onChange={setField('valueText')}/><Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',sm:'repeat(3,minmax(0,1fr))'},gap:1}}><TextField label="Unidad" value={field('unit')} disabled/><TextField label="Ref. mínima" value={field('referenceMin')} disabled/><TextField label="Ref. máxima" value={field('referenceMax')} disabled/></Box>{field('referenceText')?<Alert severity="info">Referencia: {field('referenceText')}</Alert>:null}<TextField label="Notas" multiline minRows={2} value={field('notes')} onChange={setField('notes')}/></Stack>;case'study':return <Stack gap={1.1}>{professionalSelect}<TextField label="Título *" value={field('title')} onChange={setField('title')}/><TextField label="Zona anatómica" value={field('bodySite')} onChange={setField('bodySite')}/><DateParts name="scheduledAt" label="Programado" withTime/><TextField label="Hallazgos" multiline minRows={3} value={field('findings')} onChange={setField('findings')}/><TextField label="Impresión diagnóstica" multiline minRows={3} value={field('impression')} onChange={setField('impression')}/></Stack>;case'hospitalization':return <Stack gap={1.1}>{professionalSelect}<DateParts name="admittedAt" label="Ingreso" withTime/><TextField label="Área / sala" value={field('ward')} onChange={setField('ward')}/><TextField label="Jaula" value={field('cage')} onChange={setField('cage')}/><TextField label="Motivo *" multiline minRows={2} value={field('reason')} onChange={setField('reason')}/><TextField label="Diagnóstico inicial" multiline minRows={2} value={field('diagnosis')} onChange={setField('diagnosis')}/></Stack>;case'observation':return <Stack gap={1.1}><TextField select label="Hospitalización *" value={field('hospitalizationId')} onChange={setField('hospitalizationId')}>{hospitalizations.filter((x)=>!['discharged','cancelled'].includes(x.status)).map((x)=><MenuItem key={x.id} value={x.id}>{x.admissionNumber} · {x.patientName||selectedPatient?.displayName}</MenuItem>)}</TextField>{professionalSelect}<TextField label="Temperatura" value={field('temperature')} onChange={setField('temperature')}/><TextField label="Frecuencia cardíaca" value={field('heartRate')} onChange={setField('heartRate')}/><TextField label="Peso" value={field('weight')} onChange={setField('weight')}/><TextField label="Observación" multiline minRows={3} value={field('note')} onChange={setField('note')}/></Stack>;case'procedure':return <Stack gap={1.1}>{professionalSelect}<TextField label="Procedimiento *" value={field('name')} onChange={setField('name')}/><TextField label="Tipo" value={field('kind','procedure')} onChange={setField('kind')}/><DateParts name="scheduledAt" label="Programado" withTime/><TextField label="Anestesia" value={field('anesthesia')} onChange={setField('anesthesia')}/><TextField label="Notas" multiline minRows={3} value={field('notes')} onChange={setField('notes')}/><TextField label="Resultado" multiline minRows={2} value={field('outcome')} onChange={setField('outcome')}/></Stack>;default:return null;}};
  return <><Box className="cg-veterinary-workspace" sx={{display:'grid',gap:1.4,minWidth:0}}>{baseError?<Alert severity="error" action={<Button color="inherit" size="small" onClick={()=>void loadBase()}>Reintentar</Button>}>No se pudo actualizar el resumen veterinario. Se conserva la última información válida. {baseError}</Alert>:null}{patientDataError?<Alert severity="warning" action={<Button color="inherit" size="small" onClick={()=>void loadPatientData(selectedPatientId)} disabled={!selectedPatientId}>Reintentar</Button>}>No se pudo actualizar la historia del paciente. Se conserva la última información válida. {patientDataError}</Alert>:null}{actionError?<Alert severity="error" onClose={()=>setActionError('')}>{actionError}</Alert>:null}<Paper variant="outlined" sx={{p:{xs:1.3,md:1.7},display:'flex',flexWrap:'wrap',justifyContent:'space-between',alignItems:'center',gap:1}}><Box sx={{minWidth:0}}><Typography variant="caption" color="primary" sx={{textTransform:'uppercase',letterSpacing:'.08em',fontWeight:600}}>Vertical veterinaria</Typography><Typography variant="h4">Clínica veterinaria</Typography><Typography variant="body2" color="text.secondary">Mascotas, agenda, historia clínica, laboratorio, hospitalización y seguimiento en una sola vista.</Typography></Box><Stack direction="row" gap={.7} flexWrap="wrap"><Button variant="outlined" onClick={()=>openDialog('professional',{specialty:'Medicina veterinaria general'})}>Profesional</Button><Button variant="outlined" onClick={refreshAll}>Actualizar</Button><Button startIcon={<Icon name="fa-plus"/>} onClick={()=>openDialog('patient')}>Nueva mascota</Button></Stack></Paper><Box sx={{display:'grid',gridTemplateColumns:{xs:'repeat(2,minmax(0,1fr))',md:'repeat(3,minmax(0,1fr))',xl:'repeat(6,minmax(0,1fr))'},gap:1}}><Metric icon="fa-paw" label="Mascotas activas" value={dashboard.patients||patients.length}/><Metric icon="fa-calendar-check" label="Citas de hoy" value={dashboard.appointmentsToday?.total||0} hint={`${dashboard.appointmentsToday?.pending||0} pendientes`} tone="success"/><Metric icon="fa-flask-vial" label="Laboratorios" value={dashboard.pendingLabOrders||0} hint="pendientes" tone="secondary"/><Metric icon="fa-triangle-exclamation" label="Resultados alerta" value={dashboard.abnormalResults||0} tone="warning"/><Metric icon="fa-house-medical" label="Hospitalizados" value={dashboard.hospitalized||0} tone="error"/><Metric icon="fa-syringe" label="Vacunas próximas" value={dashboard.vaccinesDue||0} tone="success"/></Box><Paper variant="outlined" sx={{px:1,overflow:'hidden'}}><Tabs value={tab} onChange={changeTab} variant="scrollable" scrollButtons="auto" allowScrollButtonsMobile>{TABS.map(([key,label,icon])=><Tab key={key} value={key} icon={<Icon name={icon}/>} iconPosition="start" label={label}/>)}</Tabs></Paper>{loading?<Paper variant="outlined" sx={{p:4,textAlign:'center'}}><CircularProgress size={30}/><Typography variant="body2" mt={1}>Cargando módulo veterinario…</Typography><LinearProgress sx={{mt:2}}/></Paper>:renderTab()}</Box><Dialog open={Boolean(dialog)} onClose={guardedDialogClose} disableEscapeKeyDown keepMounted fullScreen={mobile} fullWidth maxWidth={['patient','encounter','labOrder','study','hospitalization','procedure'].includes(dialog)?'md':'sm'}><DialogTitle sx={{p:'14px 16px',display:'flex',alignItems:'center',justifyContent:'space-between',gap:1}}><Box><Typography sx={{fontWeight:700,fontSize:'1rem'}}>{dialogTitle}</Typography><Typography variant="caption" color="text.secondary">Los cambios solo se descartan con Cancelar o cerrar.</Typography></Box><IconButton onClick={closeDialog} disabled={busy} aria-label="Cerrar"><Icon name="fa-xmark" size={17}/></IconButton></DialogTitle><DialogContent dividers sx={{pt:1.7,pb:2}}>{renderDialogFields()}</DialogContent><DialogActions sx={{px:2,py:1.3}}><Button onClick={closeDialog} disabled={busy} color="inherit">Cancelar</Button><Button onClick={submit} disabled={busy} startIcon={busy?<CircularProgress size={14} color="inherit"/>:<Icon name="fa-floppy-disk"/>}>{field('_entityId')?'Guardar cambios':'Guardar'}</Button></DialogActions></Dialog></>;
}
